#!/bin/bash
# GhostCore Forensic Menu

while true; do
    clear
    echo "=========================================="
    echo "     GhostCore Forensic Toolkit"
    echo "=========================================="
    echo ""
    echo "  1) Launch GUI Scanner (Meliodas Counter)"
    echo "  2) Mount Windows Partition"
    echo "  3) Network Scanner"
    echo "  4) Forensic Tamper Check"
    echo "  5) Inject GodMode+ Panel"
    echo "  6) Parse Offline Registry"
    echo "  7) Open Terminal"
    echo "  8) Shutdown"
    echo "  9) Reboot"
    echo ""
    read -p "Select option: " choice

    case $choice in
        1) python3 /opt/ghostcore/tools/meliodas_counter.py ;;
        2) /opt/ghostcore/scripts/mount-windows.sh ;;
        3) python3 /opt/ghostcore/tools/network_scanner.py ;;
        4) python3 /opt/ghostcore/tools/forensic_tamper_check.py ;;
        5) python3 /opt/ghostcore/tools/godmode_panel.py ;;
        6) python3 /opt/ghostcore/tools/registry_parser.py ;;
        7) /bin/bash ;;
        8) shutdown -h now ;;
        9) reboot ;;
        *) echo "Invalid option" ;;
    esac

    echo ""
    read -p "Press Enter to continue..."
done

